    if (/\bGPIO[ABC]->IDR\s*(?:[&|^]?=)(?!=)/.test(read)) { setFeedback(`Incorrect: this box needs a condition, but your code tries to assign to IDR. IDR is read-only. Read IDR in the condition and use a mask to isolate the selected pin.`, 'error', 'read'); return false; }
