  $('editor-heading').closest('.editor').classList.toggle('assemble-active', mode !== 'scratch');
  $('editor-heading').closest('.editor').classList.toggle('select-active', mode === 'select');
  $('editor-heading').closest('.editor').classList.toggle('token-active', mode === 'assemble');
