renderCodeSections(); setMode('select'); resetMachine();

function setupReferenceCard() {
  const card = $('reference-card');
  if (!card) return;
  const buttons = [...card.querySelectorAll('.reference-topic')];
  const panels = [...card.querySelectorAll('.reference-panel')];
  buttons.forEach(button => button.addEventListener('click', () => {
    const opening = button.getAttribute('aria-expanded') !== 'true';
    buttons.forEach(other => {
      const active = opening && other === button;
      other.setAttribute('aria-expanded', String(active));
      other.querySelector('.reference-topic-icon').textContent = active ? '−' : '+';
    });
    panels.forEach(panel => { panel.hidden = !(opening && panel.id === button.dataset.topic); });
  }));
}
setupReferenceCard();
